import{_ as o,o as t,c as a,a2 as d}from"./chunks/framework.BN3Eol-0.js";const g=JSON.parse('{"title":"UXD-037 — The orbit bands, and the old teal in the UI, leave #4ecdc4 and #7fd9d2","description":"","frontmatter":{},"headers":[],"relativePath":"uxs/decisions/UXD-037-orbit-band-palette-no-teal.md","filePath":"uxs/decisions/UXD-037-orbit-band-palette-no-teal.md"}'),n={name:"uxs/decisions/UXD-037-orbit-band-palette-no-teal.md"};function c(r,e,s,i,l,h){return t(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="uxd-037-—-the-orbit-bands-and-the-old-teal-in-the-ui-leave-4ecdc4-and-7fd9d2" tabindex="-1">UXD-037 — The orbit bands, and the old teal in the UI, leave #4ecdc4 and #7fd9d2 <a class="header-anchor" href="#uxd-037-—-the-orbit-bands-and-the-old-teal-in-the-ui-leave-4ecdc4-and-7fd9d2" aria-label="Permalink to &quot;UXD-037 — The orbit bands, and the old teal in the UI, leave #4ecdc4 and #7fd9d2&quot;">​</a></h1><ul><li><strong>Status</strong>: accepted (built; checked by unit tests, <code>accent-colour.spec.ts</code> on three projects and screenshots, not yet by the operator)</li><li><strong>Date</strong>: 2026-11-14</li><li><strong>Decider</strong>: the operator, 2026-11-14 (&quot;yes on losing old teal&quot;); the proposal and its swatch sheet (contrast and distance numbers below) approved as written, Earth MEO included</li><li><strong>Answers</strong>: the 0.9.9 arc&#39;s &quot;replace the site-wide <code>#4ecdc4</code>&quot; in the places <a href="./UXD-001-ui-accent-blue-replaces-teal">UXD-001</a> and <a href="./UXD-024-orbit-ruler-one-row-draws-its-regime">UXD-024</a> had left as data colours</li><li><strong>Builds on</strong>: UXD-001 (no teal in rings, states, chips), UXD-024 (the ruler draws the regime in the highlight blue <code>#889fe7</code>; the regime colour stays on the dot, the chip and the panel eyebrow)</li><li><strong>Changes</strong>: <code>static/data/orbit-regimes{,-moon,-mars,-explore}.json</code>, <code>earth-objects.json</code> (ISS), <code>explore-orbiters.json</code> (MRO, MAVEN, Juno), <code>trajectories/voyager-2.json</code>, <code>src/lib/explore/paths-legend.ts</code>, <code>src/lib/epoch-bands.ts</code>, <code>DebugPanel.svelte</code>, the two <code>dev/</code> routes, <code>tests/e2e/accent-colour.spec.ts</code>; <code>05_Design_System.md</code> §2.5 and the contrast rule, UXD-025</li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>The orbit bands still wore the old accent: LEO, LLO, LMO and the explore TERRESTRIAL zone <code>#4ecdc4</code>, HLO, HMO and KUIPER <code>#7fd9d2</code>. The two were 10 apart (CIE76 ΔE) on the Moon and on Mars, so the lowest two bands read as one. Earth MEO <code>#7b9cff</code> was 15 from the highlight blue <code>#889fe7</code>, so a selected MEO row looked like a hovered row.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><ol><li><strong>Two band hues, shared by every world.</strong> The lowest band (LEO, LLO, LMO, TERRESTRIAL) is <code>#8fd16a</code> (green, hue 98; 11.2:1 on <code>#04040c</code>; ΔE 97 from the highlight blue). The second band (HLO, HMO, KUIPER, and Earth MEO) is <code>#f28bb8</code> (rose, hue 334; 8.9:1; ΔE 48). Both clear 5.7:1 on the 22 % hover tint of a chip. Neighbouring bands are at least 46 apart (the old HLO/LLO pair was 10). The other bands keep their colours.</li><li><strong>The old teal in the rest of the UI</strong> takes the same green: ISS, MRO, MAVEN, Juno (object identity), the commercial-era band of the timeline strip; its Skylab band (<code>#5fc4e0</code>, a cyan the guard found once the <code>--band-color</code> exemption went) is magenta <code>#da47eb</code>; and the <code>?debug=1</code> panel and the two <code>dev/</code> routes take the highlight blue. Voyager 2&#39;s path (the one teal line of the PATHS legend, in <code>paths-legend.ts</code> and its trajectory file) is <code>#da47eb</code> (magenta): the other 17 path colours are pastel and crowded, green sat 13 from <code>#b2e066</code>, magenta is 46 or more from every other path.</li><li><strong>Kept</strong>: Lab art and science diagrams (UXD-001); the Kármán limb glow, the tides and the tidal-lock overlay of the 3D scenes (physical look, not UI; WebGL pixels are outside the guard).</li><li><strong>The guard now covers the bands.</strong> <code>accent-colour.spec.ts</code> no longer exempts <code>--regime-color</code> or <code>--band-color</code>; a band that goes teal again fails it. <code>--accent</code> (the fleet category colour) stays exempt until the fleet page&#39;s own change.</li></ol><h2 id="not-decided-here" tabindex="-1">Not decided here <a class="header-anchor" href="#not-decided-here" aria-label="Permalink to &quot;Not decided here&quot;">​</a></h2><p>Earth MOON <code>#aaaacc</code> (ΔE 22 from the highlight blue), NRHO and SCATTERED <code>#9c6ee0</code> (36), OORT <code>#1e3a8a</code> (1.97:1 as text) and BELT <code>#8b6f47</code> (4.34:1) are not teal and are unchanged.</p>',8)])])}const u=o(n,[["render",c]]);export{g as __pageData,u as default};
